import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.cT4_XGNl.js";const m=JSON.parse('{"title":"Project Pitch: Next-Gen Creative Blog Platform","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),o={name:"00b-project-pitch.md"};function n(s,e,c,l,d,h){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="project-pitch-next-gen-creative-blog-platform" tabindex="-1">Project Pitch: Next-Gen Creative Blog Platform <a class="header-anchor" href="#project-pitch-next-gen-creative-blog-platform" aria-label="Permalink to &quot;Project Pitch: Next-Gen Creative Blog Platform&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><p>&quot;I built a high-performance creative publishing platform that bridges the gap between high-end editorial storytelling and interactive 3D WebGL experiences. Built with React 19, Three.js via React Three Fiber, Node.js, and MongoDB, it features 60fps inertial smooth scrolling, real-time magnetic physics, and an interactive spatial hero canvas. On the backend, it delivers a secure REST API with JWT identity protection, auto-generated nanoid slugs, threaded comments, and a Cloudinary asset pipeline. It transforms passive reading into an engaging sensory experience while scaling seamlessly across devices.&quot;</p><h2 id="_2-minute-comprehensive-pitch" tabindex="-1">2-Minute Comprehensive Pitch <a class="header-anchor" href="#_2-minute-comprehensive-pitch" aria-label="Permalink to &quot;2-Minute Comprehensive Pitch&quot;">​</a></h2><p>&quot;Modern digital editorial platforms often suffer from two extremes: either they are hyper-minimalist and visually sterile, or they are bloated with heavy, laggy third-party scripts that compromise user experience.</p><p>To solve this, I designed and engineered the Next-Gen Creative Blog Platform. On the frontend, I leveraged React 19 and Vite with a custom graphics pipeline combining Three.js, React Three Fiber, and Drei. Readers are greeted by an interactive 3D spatial canvas that smoothly reacts to cursor position and lighting vectors, combined with Lenis smooth inertial scrolling, GSAP animations, and custom magnetic physics on interactive buttons.</p><p>Under the hood, the backend is powered by Node.js and Express running in modern ES module mode. I implemented a robust MVC architecture with Mongoose ODM models for Users, Blogs, Comments, and Notifications. Story creation is frictionless: authors draft rich posts, attach cover images that are automatically optimized and served via the Cloudinary Media CDN, and get URL-safe cryptographic slugs generated via Nanoid.</p><p>Security and reliability were first-class priorities: passwords are salted and hashed using 10 rounds of bcrypt, APIs are secured with stateless HS256 JWT tokens, and complex operations like blog deletion cascade cleanly across linked comments and notifications. In load tests, the decoupled stateless architecture handles high concurrent read traffic effortlessly, making it an ideal showcase for production-grade full-stack engineering.&quot;</p>',8)])])}const g=t(o,[["render",n]]);export{m as __pageData,g as default};
